SELECT id, 't_rr_e_n1_max', '{"parameter":"t_rr_e_n1_max"}'::jsonb, NULL, 't_RR,E,n=1 — Einstaudauer des Retentionsraums (Mischsystem)', 5, '{"wert":48,"unit":"h","comparator":"≤","modal":"muss","text":"Im Mischsystem muss die Einstaudauer des Retentionsraums für $n=1 \\leq 48 \\mathrm{~h}$ sein. Die Beschickungshäufigkeit muss im langjährigen Mittel $\\geq 10$ a sein."}'::jsonb, 'Im Mischsystem muss die Einstaudauer des Retentionsraums für $n=1 \leq 48 \mathrm{~h}$ sein. Die Beschickungshäufigkeit muss im langjährigen Mittel $\geq 10$ a sein.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
