SELECT id, 'n_rbf_min', '{"parameter":"n_rbf_min"}'::jsonb, NULL, 'Beschickungshäufigkeit im langjährigen Mittel (gedruckt „≥ 10 a“; §3.2 druckt n_RBF in 1/a — a178-U-5)', 6, '{"wert":10,"unit":"a","comparator":"≥","modal":"muss","text":"Im Mischsystem muss die Einstaudauer des Retentionsraums für $n=1 \\leq 48 \\mathrm{~h}$ sein. Die Beschickungshäufigkeit muss im langjährigen Mittel $\\geq 10$ a sein."}'::jsonb, 'Im Mischsystem muss die Einstaudauer des Retentionsraums für $n=1 \leq 48 \mathrm{~h}$ sein. Die Beschickungshäufigkeit muss im langjährigen Mittel $\geq 10$ a sein.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
