INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_rr_min', '{"parameter":"h_rr_min"}'::jsonb, NULL, 'h_RR — nutzbare Einstauhöhe, untere Grenze', 7, '{"wert":0.3,"unit":"m","comparator":"≥","modal":"liegen zwischen","text":"Der Retentionsraum dient der Zwischenspeicherung der durch Filtration zu behandelnden Abflüsse. Weiterhin findet im Retentionsraum von Durchlauffilterbecken eine Sedimentation statt, die den über den Filterbeckenüberlauf entlasteten Volumenstrom mechanisch reinigt. Bei diesen Anlagen sollte der Retentionsraum deshalb so gestaltet werden, dass eine gleichmäßige Durchströmung möglich ist. Nutzbare Einstauhöhen liegen zwischen $h_{R R}=0,3 \\mathrm{~m}$ und 2 m ."}'::jsonb, 'Der Retentionsraum dient der Zwischenspeicherung der durch Filtration zu behandelnden Abflüsse. Weiterhin findet im Retentionsraum von Durchlauffilterbecken eine Sedimentation statt, die den über den Filterbeckenüberlauf entlasteten Volumenstrom mechanisch reinigt. Bei diesen Anlagen sollte der Retentionsraum deshalb so gestaltet werden, dass eine gleichmäßige Durchströmung möglich ist. Nutzbare Einstauhöhen liegen zwischen $h_{R R}=0,3 \mathrm{~m}$ und 2 m .' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'h_rr_max', '{"parameter":"h_rr_max"}'::jsonb, NULL, 'h_RR — nutzbare Einstauhöhe, obere Grenze', 8, '{"wert":2,"unit":"m","comparator":"≤","modal":"liegen zwischen","text":"Der Retentionsraum dient der Zwischenspeicherung der durch Filtration zu behandelnden Abflüsse. Weiterhin findet im Retentionsraum von Durchlauffilterbecken eine Sedimentation statt, die den über den Filterbeckenüberlauf entlasteten Volumenstrom mechanisch reinigt. Bei diesen Anlagen sollte der Retentionsraum deshalb so gestaltet werden, dass eine gleichmäßige Durchströmung möglich ist. Nutzbare Einstauhöhen liegen zwischen $h_{R R}=0,3 \\mathrm{~m}$ und 2 m ."}'::jsonb, 'Der Retentionsraum dient der Zwischenspeicherung der durch Filtration zu behandelnden Abflüsse. Weiterhin findet im Retentionsraum von Durchlauffilterbecken eine Sedimentation statt, die den über den Filterbeckenüberlauf entlasteten Volumenstrom mechanisch reinigt. Bei diesen Anlagen sollte der Retentionsraum deshalb so gestaltet werden, dass eine gleichmäßige Durchströmung möglich ist. Nutzbare Einstauhöhen liegen zwischen $h_{R R}=0,3 \mathrm{~m}$ und 2 m .' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'q_dr_rbf_max', '{"parameter":"q_dr_rbf_max"}'::jsonb, NULL, 'q_Dr,RBF — spezifische Drosselabflussspende bei Volleinstau', 9, '{"wert":0.05,"unit":"l/(s·m²)","comparator":"≤","modal":"ist sicherzustellen … begrenzt","text":"Die Drosselung des Dränabflusses dient der Einhaltung der Filtergeschwindigkeit und damit auch der Vergleichmäßigung der Filterflächenbelastung. Es ist sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\\text {Dr,RBF }}=0,05 \\mathrm{l} /\\left(\\mathrm{s} \\cdot \\mathrm{m}^{2}\\right)$ begrenzt ist. Eine Steuerung oder Regelung des Drosselabflusses ist nicht erforderlich."}'::jsonb, 'Die Drosselung des Dränabflusses dient der Einhaltung der Filtergeschwindigkeit und damit auch der Vergleichmäßigung der Filterflächenbelastung. Es ist sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\text {Dr,RBF }}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Eine Steuerung oder Regelung des Drosselabflusses ist nicht erforderlich.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'kdb_min_mm', '{"parameter":"kdb_min_mm"}'::jsonb, NULL, 'Kunststoffdichtungsbahn — Mindeststärke', 10, '{"wert":2,"unit":"mm","comparator":"≥","modal":"muss","text":"Die Abdichtung gewährleistet dauerhaft einen kontrollierten Filterbetrieb und die Möglichkeit des Einstaus und ist daher zwingend erforderlich. Die Abdichtung muss mit Kunststoffdichtungsbahnen einer Stärke von mindestens 2 mm ausgeführt werden. Die Abdichtung ist beidseitig gegen mechanische Beschädigungen durch ein Geotextil zu schützen. Grundsätze und Ausführungsbeispiele sind im Merkblatt DWA-M 176 dargestellt."}'::jsonb, 'Die Abdichtung gewährleistet dauerhaft einen kontrollierten Filterbetrieb und die Möglichkeit des Einstaus und ist daher zwingend erforderlich. Die Abdichtung muss mit Kunststoffdichtungsbahnen einer Stärke von mindestens 2 mm ausgeführt werden. Die Abdichtung ist beidseitig gegen mechanische Beschädigungen durch ein Geotextil zu schützen. Grundsätze und Ausführungsbeispiele sind im Merkblatt DWA-M 176 dargestellt.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'u_max', '{"parameter":"u_max"}'::jsonb, NULL, 'U = d_60/d_10 — Ungleichförmigkeitsgrad des Filtermaterials', 11, '{"wert":5,"unit":"-","comparator":"<","modal":"muss … eingehalten werden","text":"Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \\mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\\mathrm{G}_{\\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\\leq 15$ Massen- $\\%$ und ein maximaler Feinanteil $(<0,063 \\mathrm{~mm})$ von $\\leq 3$ Massen- $\\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden."}'::jsonb, 'Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\mathrm{G}_{\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\leq 15$ Massen- $\%$ und ein maximaler Feinanteil $(<0,063 \mathrm{~mm})$ von $\leq 3$ Massen- $\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'feinanteil_max', '{"parameter":"feinanteil_max"}'::jsonb, NULL, 'Feinanteil (< 0,063 mm) des Filtermaterials', 12, '{"wert":3,"unit":"Massen-%","comparator":"≤","modal":"festgelegt","text":"Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \\mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\\mathrm{G}_{\\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\\leq 15$ Massen- $\\%$ und ein maximaler Feinanteil $(<0,063 \\mathrm{~mm})$ von $\\leq 3$ Massen- $\\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden."}'::jsonb, 'Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\mathrm{G}_{\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\leq 15$ Massen- $\%$ und ein maximaler Feinanteil $(<0,063 \mathrm{~mm})$ von $\leq 3$ Massen- $\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
