INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'ueberkorn_max', '{"parameter":"ueberkorn_max"}'::jsonb, NULL, 'Überkornanteil des Filtermaterials', 13, '{"wert":15,"unit":"Massen-%","comparator":"≤","modal":"festgelegt","text":"Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \\mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\\mathrm{G}_{\\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\\leq 15$ Massen- $\\%$ und ein maximaler Feinanteil $(<0,063 \\mathrm{~mm})$ von $\\leq 3$ Massen- $\\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden."}'::jsonb, 'Die genannten Anforderungen werden mehrheitlich mit natürlichen Gesteinskörnungen aus mineralischen Vorkommen, wie z. B. Quarz, Basalt, Kalkbrechsand, Lava, erreicht. Eine ausreichende Basenausstattung muss unter Umständen durch Zumischung von Calciumcarbonat hergestellt werden. Bindige Böden, organische Beimischungen und rezyklierte Gesteinskörnungen dürfen nicht verwendet werden. Wie bei der Deckschicht sollten die verwendeten Filtermaterialien frost- und tausalzbeständig sein. Als Filtermaterial sind kantengerundete und gebrochene Materialien aus natürlichen Vorkommen der Korngruppe $0 / 2 \mathrm{~mm}$ nach TL Gestein-StB 04/07 (Kategorie $\mathrm{G}_{\mathrm{F}} 85$, Gehalt an Feinanteilen $f_{3}$ ) geeignet. Es ist demnach unter anderem ein maximaler Überkornanteil von $\leq 15$ Massen- $\%$ und ein maximaler Feinanteil $(<0,063 \mathrm{~mm})$ von $\leq 3$ Massen- $\%$ festgelegt. Feinanteile sind ebenso wie Überkornanteile nachteilig für den Filterbetrieb und die Reinigungsleistung. Es muss eine steile Körnungslinie mit $U=d_{60} / d_{10}<5$ eingehalten werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'caco3_min', '{"parameter":"caco3_min"}'::jsonb, NULL, 'Calciumcarbonatgehalt des Filtermaterials', 14, '{"wert":20,"unit":"Massen-%","comparator":"≥","modal":"muss","text":"Das Filtermaterial muss einen Calciumcarbonatgehalt von $\\geq 20$ Massen- $\\%$ aufweisen. Der geforderte Calciumcarbonatgehalt kann bei geringer Ausstattung der regional vorkommenden Gesteinskörnungen durch technisches Zumischen carbonatreichen Materials erreicht werden. Der carbonatische Anteil im Filtermaterial sollte im oberen zulässigen Korngrößenspektrum liegen, um einen raschen Austrag aus dem Filterkörper zu vermeiden. Die Anforderungen an die Korngrößenverteilung des Filtermaterials beziehen sich immer auf das eingebaute Material, schließen die gegebenenfalls erforderlichen Carbonatzumischungen ein. Auch die Schadstofffreiheit bezieht sich auf das gegebenenfalls meliorierte Filtermaterial."}'::jsonb, 'Das Filtermaterial muss einen Calciumcarbonatgehalt von $\geq 20$ Massen- $\%$ aufweisen. Der geforderte Calciumcarbonatgehalt kann bei geringer Ausstattung der regional vorkommenden Gesteinskörnungen durch technisches Zumischen carbonatreichen Materials erreicht werden. Der carbonatische Anteil im Filtermaterial sollte im oberen zulässigen Korngrößenspektrum liegen, um einen raschen Austrag aus dem Filterkörper zu vermeiden. Die Anforderungen an die Korngrößenverteilung des Filtermaterials beziehen sich immer auf das eingebaute Material, schließen die gegebenenfalls erforderlichen Carbonatzumischungen ein. Auch die Schadstofffreiheit bezieht sich auf das gegebenenfalls meliorierte Filtermaterial.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'deckschicht_cm', '{"parameter":"deckschicht_cm"}'::jsonb, NULL, 'Deckschicht — Stärke', 15, '{"wert":5,"unit":"cm","comparator":"=","modal":"besteht aus","text":"Die Deckschicht schützt die Bodenfilteroberfläche gegen Erosion und äußere Kolmation, solange die Filtervegetation noch nicht etabliert ist. Sie besteht aus einer 5 cm starken Schicht aus kantengerundetem oder gebrochenem mineralischem Material ( 2 mm bis 8 mm ). Das Material der Deckschicht sollte frost- und tausalzbeständig sein."}'::jsonb, 'Die Deckschicht schützt die Bodenfilteroberfläche gegen Erosion und äußere Kolmation, solange die Filtervegetation noch nicht etabliert ist. Sie besteht aus einer 5 cm starken Schicht aus kantengerundetem oder gebrochenem mineralischem Material ( 2 mm bis 8 mm ). Das Material der Deckschicht sollte frost- und tausalzbeständig sein.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'langzeitsimulation_min_a', '{"parameter":"langzeitsimulation_min_a"}'::jsonb, NULL, 'Kontinuumssimulation — Mindestdauer der Niederschlagsbelastung', 16, '{"wert":10,"unit":"a","comparator":"≥","modal":"basiert auf … mindestens","text":"Der Nachweis der Retentionsbodenfilteranlage im Trenn- und Mischsystem basiert auf einer Kontinuumssimulation mit mindestens 10 Jahren Niederschlagsbelastung. Das Modell bezieht sich hierbei auf die Retentionsbodenfilteranlage und umfasst somit die Vorstufe einschließlich einstauender Kanalnetzvolumina sowie das Retentionsbodenfilterbecken."}'::jsonb, 'Der Nachweis der Retentionsbodenfilteranlage im Trenn- und Mischsystem basiert auf einer Kontinuumssimulation mit mindestens 10 Jahren Niederschlagsbelastung. Das Modell bezieht sich hierbei auf die Retentionsbodenfilteranlage und umfasst somit die Vorstufe einschließlich einstauender Kanalnetzvolumina sowie das Retentionsbodenfilterbecken.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_LIMITS' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-A-178', '2019-06', 'S6_2_RECHENWERTE', 'Rechenwerte und Vorgaben der Bemessung (§6.2.2, gedruckte Sätze)', '§6.2.2.1, §6.2.2.2', NULL, ARRAY['parameter']::text[], '[{"name":"wert","type":"number"},{"name":"unit","type":"string"},{"name":"comparator","type":"string"},{"name":"modal","type":"string"},{"name":"text","type":"string"}]'::jsonb, 'locked', 'Die AFS63-Zulauffracht zum Retentionsbodenfilter kann über mittlere spezifische Jahresfrachtpotenziale ( $b_{\mathrm{R}, \mathrm{a}}$ ), bezogen auf $A_{\mathrm{E}, \mathrm{b}, \mathrm{a},}$ abgeschätzt werden. Als Rechenwert zur Vorbemessung der Bodenfilteroberfläche wird eine flächenspezifische Fracht von $b_{\mathrm{R}, \mathrm{a}}=530 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ angesetzt. Bei der Zulauffrachtermittlung im Rahmen der Nachweisführung sind alle Komponenten des Entwässerungssystems zu berücksichtigen, die zu einer Frachtminderung beitragen (z. B. vorgelagerte Regenbecken, Entlastungen, Grabensysteme etc.).', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'b_r_a', '{"parameter":"b_r_a"}'::jsonb, NULL, 'b_R,a — Rechenwert des spezifischen AFS63-Jahresfrachtpotenzials (Vorbemessung)', 0, '{"wert":530,"unit":"kg/(ha·a)","comparator":"=","modal":"wird … angesetzt","text":"Die AFS63-Zulauffracht zum Retentionsbodenfilter kann über mittlere spezifische Jahresfrachtpotenziale ( $b_{\\mathrm{R}, \\mathrm{a}}$ ), bezogen auf $A_{\\mathrm{E}, \\mathrm{b}, \\mathrm{a},}$ abgeschätzt werden. Als Rechenwert zur Vorbemessung der Bodenfilteroberfläche wird eine flächenspezifische Fracht von $b_{\\mathrm{R}, \\mathrm{a}}=530 \\mathrm{~kg} /(\\mathrm{ha} \\cdot \\mathrm{a})$ angesetzt. Bei der Zulauffrachtermittlung im Rahmen der Nachweisführung sind alle Komponenten des Entwässerungssystems zu berücksichtigen, die zu einer Frachtminderung beitragen (z. B. vorgelagerte Regenbecken, Entlastungen, Grabensysteme etc.)."}'::jsonb, 'Die AFS63-Zulauffracht zum Retentionsbodenfilter kann über mittlere spezifische Jahresfrachtpotenziale ( $b_{\mathrm{R}, \mathrm{a}}$ ), bezogen auf $A_{\mathrm{E}, \mathrm{b}, \mathrm{a},}$ abgeschätzt werden. Als Rechenwert zur Vorbemessung der Bodenfilteroberfläche wird eine flächenspezifische Fracht von $b_{\mathrm{R}, \mathrm{a}}=530 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ angesetzt. Bei der Zulauffrachtermittlung im Rahmen der Nachweisführung sind alle Komponenten des Entwässerungssystems zu berücksichtigen, die zu einer Frachtminderung beitragen (z. B. vorgelagerte Regenbecken, Entlastungen, Grabensysteme etc.).' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_RECHENWERTE'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'porenvolumen_pct', '{"parameter":"porenvolumen_pct"}'::jsonb, NULL, 'Nutzbares Porenvolumen des Filterkörpers (Anteil des Filterkörpervolumens)', 1, '{"wert":15,"unit":"%","comparator":"=","modal":"wird pauschal … angesetzt","text":"Das nutzbare Retentionsvolumen des Retentionsbodenfilterbeckens ( $V_{\\text {RBF }}$ ) ergibt sich aus dem Volumen des Retentionsraums und dem nutzbaren Porenvolumen des Filterkörpers. Das Porenvolumen wird pauschal mit $15 \\%$ des Filterkörpervolumens angesetzt. Die Böschungsneigung des Retentionsraums ergibt sich aus der örtlichen Situation und der konstruktiven Gestaltung."}'::jsonb, 'Das nutzbare Retentionsvolumen des Retentionsbodenfilterbeckens ( $V_{\text {RBF }}$ ) ergibt sich aus dem Volumen des Retentionsraums und dem nutzbaren Porenvolumen des Filterkörpers. Das Porenvolumen wird pauschal mit $15 \%$ des Filterkörpervolumens angesetzt. Die Böschungsneigung des Retentionsraums ergibt sich aus der örtlichen Situation und der konstruktiven Gestaltung.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_RECHENWERTE'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
