SELECT id, 'q_dr_rbf_vorbemessung', '{"parameter":"q_dr_rbf_vorbemessung"}'::jsonb, NULL, 'q_Dr,RBF — konstante Abflussspende für die Berechnung des Drosselabflusses (Gl. 4)', 0, '{"wert":0.05,"unit":"l/(s·m²)","comparator":"=","modal":"kann … angesetzt werden","text":"Für diese Berechnung kann eine konstante Abflussspende des Drosselorgans des Retentionsbodenfilterbeckens von $q_{\\mathrm{Dr}, \\mathrm{RBF}}=0,05 \\mathrm{l} /\\left(\\mathrm{s} \\cdot \\mathrm{m}^{2}\\right)$ gemäß 6.1.4.10 angesetzt werden. Für die nachfolgende Nachweisrechnung muss die Kennlinie des geplanten Drosselorgans angesetzt werden."}'::jsonb, 'Für diese Berechnung kann eine konstante Abflussspende des Drosselorgans des Retentionsbodenfilterbeckens von $q_{\mathrm{Dr}, \mathrm{RBF}}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ gemäß 6.1.4.10 angesetzt werden. Für die nachfolgende Nachweisrechnung muss die Kennlinie des geplanten Drosselorgans angesetzt werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_ANHALT'
