INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'pflanzdichte_min', '{"parameter":"pflanzdichte_min"}'::jsonb, NULL, 'Pflanzdichte Schilf — untere Grenze', 1, '{"wert":4,"unit":"Pflanzen/m²","comparator":"≥","modal":"haben sich … bewährt","text":"Zur Bepflanzung werden vorkultivierte Schilfpflanzen (Phragmites communis) eingesetzt. Als Pflanzdichte haben sich 4 bis 8 Pflanzen je Quadratmeter bewährt. Eine Fertigstellungspflege ist erforderlich. In der Etablierungsphase von in der Regel einer Vegetationsperiode muss die Wasser- und Nährstoffversorgung gewährleistet werden."}'::jsonb, 'Zur Bepflanzung werden vorkultivierte Schilfpflanzen (Phragmites communis) eingesetzt. Als Pflanzdichte haben sich 4 bis 8 Pflanzen je Quadratmeter bewährt. Eine Fertigstellungspflege ist erforderlich. In der Etablierungsphase von in der Regel einer Vegetationsperiode muss die Wasser- und Nährstoffversorgung gewährleistet werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_ANHALT'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'pflanzdichte_max', '{"parameter":"pflanzdichte_max"}'::jsonb, NULL, 'Pflanzdichte Schilf — obere Grenze', 2, '{"wert":8,"unit":"Pflanzen/m²","comparator":"≤","modal":"haben sich … bewährt","text":"Zur Bepflanzung werden vorkultivierte Schilfpflanzen (Phragmites communis) eingesetzt. Als Pflanzdichte haben sich 4 bis 8 Pflanzen je Quadratmeter bewährt. Eine Fertigstellungspflege ist erforderlich. In der Etablierungsphase von in der Regel einer Vegetationsperiode muss die Wasser- und Nährstoffversorgung gewährleistet werden."}'::jsonb, 'Zur Bepflanzung werden vorkultivierte Schilfpflanzen (Phragmites communis) eingesetzt. Als Pflanzdichte haben sich 4 bis 8 Pflanzen je Quadratmeter bewährt. Eine Fertigstellungspflege ist erforderlich. In der Etablierungsphase von in der Regel einer Vegetationsperiode muss die Wasser- und Nährstoffversorgung gewährleistet werden.' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_ANHALT'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'feststoffeintrag_ueblich_max', '{"parameter":"feststoffeintrag_ueblich_max"}'::jsonb, NULL, 'Übliches AFS63-Frachtaufkommen (Misch-, Trennsystem, Straßenentwässerung)', 3, '{"wert":1000,"unit":"kg/(ha·a)","comparator":"≤","modal":"üblich … bis zu","text":"Ein Eintrag feinpartikulärer Feststoffe (AFS63), der das in Misch- und Trennsystemen sowie bei der Straßenentwässerung übliche Frachtaufkommen von bis zu $1.000 \\mathrm{~kg} /(\\mathrm{ha} \\cdot \\mathrm{a})$ (FUCHS et al. 2010) deutlich überschreitet, erzeugt ein erhebliches Kolmationsrisiko. Er ist in der Regel nicht durch Abschwemmungen von den Entwässerungsflächen erklärbar, sondern auf besondere Aktivitäten oder Eigenschaften von Einzugsgebiet und Kanalnetz zurückzuführen. Zur Abschätzung des zu erwartenden Feststoffeintrags in das Retentionsbodenfilterbecken sind folgende Maßnahmen hilfreich:"}'::jsonb, 'Ein Eintrag feinpartikulärer Feststoffe (AFS63), der das in Misch- und Trennsystemen sowie bei der Straßenentwässerung übliche Frachtaufkommen von bis zu $1.000 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ (FUCHS et al. 2010) deutlich überschreitet, erzeugt ein erhebliches Kolmationsrisiko. Er ist in der Regel nicht durch Abschwemmungen von den Entwässerungsflächen erklärbar, sondern auf besondere Aktivitäten oder Eigenschaften von Einzugsgebiet und Kanalnetz zurückzuführen. Zur Abschätzung des zu erwartenden Feststoffeintrags in das Retentionsbodenfilterbecken sind folgende Maßnahmen hilfreich:' FROM regulation_tables WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_ANHALT'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-A-178' AND edition = '2019-06' AND table_code = 'S6_2_ANHALT' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-A-178', '2019-06', 'TABELLE2', 'Einfache Indikatoren zur Einschätzung des Betriebszustands des Retentionsbodenfilters', '§8.3.1, Tab. 2', NULL, ARRAY['befund']::text[], '[{"name":"bereich","type":"string"},{"name":"befund_text","type":"string"},{"name":"hinweis","type":"string"}]'::jsonb, 'anhaltswert', 'Durch eine regelmäßige Begehung des Retentionsbodenfilterbeckens können anhand von einfachen Indikatoren wertvolle Hinweise zum Betriebszustand der Anlage und zur Minderung betrieblicher Risiken gewonnen werden (siehe Tabelle 2). Weitere Hinweise sind in Arbeitsblatt DWA-A 147 enthalten.', 'md_verified')
